pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amtDeposit, uint256 amtCollect, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amtDeposit > 0);
        // keep amtCollect unrestricted to allow fuzzer to find any violating scenario

        // Initialize contract and set up basic parameters
        c.SetMinSum(0);
        c.SetLogFile(address(0)); // log not needed for this property
        c.Initialized();

        // Deposit funds as the actor
        vm.deal(actor, amtDeposit);
        vm.prank(actor);
        c.Deposit{value: amtDeposit}();

        // Record total deposited so far and the actor's balance
        uint256 totalDeposited = amtDeposit;
        uint256 actorBalanceAfterDeposit = c.balances(actor);
        uint256 contractBalanceAfterDeposit = address(c).balance;

        // Collect some amount (could be zero, could be up to the deposited amount, etc.)
        // We allow the collect to succeed or fail depending on the amount; the invariant holds either way.
        vm.prank(actor);
        try c.Collect(amtCollect) { } catch { }

        // Invariant: sum of all recorded balances equals total deposits minus total collected
        // Since we only have one actor and no external ETH outflows besides Collect,
        // totalDeposited = contractBalance + sum(balances) after all operations
        // More concretely: the actor's balance plus contract's ETH balance must equal totalDeposited minus any successful Collect amount.
        // However, since the Collect amount may not be known to succeed, we instead rely on the raw balances and the invariant:
        //   address(c).balance + c.balances(actor) == totalDeposited - amtCollectedIfSuccessful
        // But because we can't easily know if the collect succeeded in the test without using try/catch for revert on the call,
        // a simpler invariant: the sum of all recorded balances across all possible keys plus address(c).balance equals the sum of all msg.value ever received.
        // In this single-actor scenario, this reduces to:
        //   address(c).balance + c.balances(actor) == totalDeposited
        // if and only if the Collect() did NOT execute (either reverted or was never called).
        // To make it hold universally for any collect amount, we observe that after any sequence, the invariant is:
        //   address(c).balance + c.balances(actor) >= totalDeposited - (totalDeposited if collect succeeded else 0) ???
        // Instead, the invariant we choose: the contract's ETH balance plus the actor's balance is never greater than the total deposited.
        // Actually, we need a UNIVERSAL invariant. The correct one:
        //   address(c).balance + c.balances(actor) == totalDeposited - successfully_collected_amount
        // Because the fuzzer may choose amtCollect such that Collect reverts or executes the full amount, we can compute the actual condition:
        // If balances[actor] >= MinSum (0) and balances[actor] >= amtCollect, then the collect succeeds and the invariant after is:
        //   address(c).balance + c.balances(actor) == totalDeposited - amtCollect
        // Otherwise, Collect reverts and balances unchanged, contract balance unchanged.

        // We check the actual balances after the try/catch and compute the total deposited by using the fact that Deposit() added exactly amtDeposit.
        uint256 actorBal = c.balances(actor);
        uint256 contractBal = address(c).balance;

        // Derive expected: if collect succeeded (actorBal == actorBalanceAfterDeposit - amtCollect && contractBal == contractBalanceAfterDeposit - amtCollect),
        // then actorBal + contractBal == totalDeposited - amtCollect.
        // If collect reverted, actorBal + contractBal == totalDeposited.
        // We can't use internal logic to deduce whether it succeeded; instead we prove an inequality that holds in BOTH cases:
        //   address(c).balance + c.balances(actor) <= totalDeposited
        // and
        //   address(c).balance + c.balances(actor) >= totalDeposited - actorBalanceAfterDeposit  (since at most the whole actor balance can be withdrawn)
        // However, the simplest invariant that is broken by the bug: after a deposit followed by a collect, the sum of the actor's balance and the contract's ETH balance is strictly less than totalDeposited if and only if the collect was successful. BUT we can just assert that the contract holds exactly the sum of all deposited ETH not yet withdrawn.
        // Universal: address(c).balance == totalDeposited - c.balances(actor) (this holds for reference, NOT for bug).
        // Let's verify:
        // - Reference: after Deposit, actorBal = amtDeposit, contractBal = amtDeposit, totalDeposited = amtDeposit, equality holds.
        //   After Collect(amtCollect <= amtDeposit): actorBal -= amtCollect, contractBal -= amtCollect. Equality still holds.
        // - Bug: Deposit sets actorBal = 1, but contractBal = amtDeposit (since msg.value is forwarded). Then address(c).balance + c.balances(actor) = amtDeposit + 1, NOT equal to totalDeposited (which is amtDeposit).
        // Therefore, the property: address(c).balance + c.balances(actor) == totalDeposited (where totalDeposited is the sum of all msg.value sent to C via Deposit/fallback).
        // Since we only made one deposit, totalDeposited = amtDeposit.
        // The assertion holds for all inputs in the reference, but fails for the bug (when amtDeposit != 1).

        assertTrue(contractBal + actorBal == amtDeposit);
    }
}

