pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit, uint256 secondDeposit, uint256 collectAmt, address user) public {
        vm.assume(user != address(0));
        vm.assume(initialDeposit > 0 && secondDeposit > 0);
        vm.assume(collectAmt > 0 && collectAmt <= initialDeposit);
        vm.assume(initialDeposit <= type(uint256).max / 2 && secondDeposit <= type(uint256).max / 2);

        c.Initialized();
        c.SetMinSum(1);

        // First deposit
        vm.deal(user, initialDeposit);
        vm.prank(user);
        c.Deposit{value: initialDeposit}();

        // Second deposit
        vm.deal(user, secondDeposit);
        vm.prank(user);
        c.Deposit{value: secondDeposit}();

        // Collect some amount <= initialDeposit
        vm.deal(user, 0);
        vm.prank(user);
        bool ok;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // After successful collect, the balance should be initialDeposit + secondDeposit - collectAmt
        // The mutant sets balance to 1 on every deposit, so after second deposit it's 1, not the sum.
        uint256 expected = initialDeposit + secondDeposit - collectAmt;
        assertTrue(ok == false || c.balances(user) == expected);
    }
}

