pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, uint256 minSum) public {
        vm.assume(depositAmt > 0 && depositAmt <= type(uint256).max / 2);
        vm.assume(collectAmt > 0 && collectAmt <= type(uint256).max / 2);
        vm.assume(minSum > 0 && minSum <= type(uint256).max / 2);

        // Ensure contract is initialized
        c.Initialized();
        c.SetMinSum(minSum);

        address user = address(0x100);
        vm.deal(user, depositAmt * 2);

        // Deposit first
        vm.prank(user);
        c.Deposit{value: depositAmt}();

        // Collect second
        vm.prank(user);
        c.Collect(collectAmt);

        // Verify invariant: contract balance must be at least the sum of all individual balances
        // In the reference version, balances[user] reflects actual deposits minus collects.
        // In the buggy version, deposit subtracts, so balances[user] is less than actual.
        uint256 contractBalance = address(c).balance;
        uint256 recordedBalance = c.balances(user);

        // The contract balance must be at least the recorded balance of the user
        // (since the contract could also hold funds for other users)
        assertTrue(contractBalance >= recordedBalance);
    }
}

