pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 collectAmount) public {
        // Bound values to avoid overflow and ensure collectAmount <= deposit1 + deposit2
        vm.assume(deposit1 > 0);
        vm.assume(deposit2 > 0);
        vm.assume(deposit1 + deposit2 > deposit1); // no overflow
        uint256 totalDeposited = deposit1 + deposit2;
        vm.assume(collectAmount > 0 && collectAmount <= totalDeposited);

        // Setup: user1 deposits deposit1, user2 deposits deposit2
        address user1 = address(1);
        address user2 = address(2);
        vm.deal(user1, deposit1);
        vm.deal(user2, deposit2);

        // Initialize the contract and set up LogFile
        c.Initialized();
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));

        vm.prank(user1);
        c.Deposit{value: deposit1}();
        vm.prank(user2);
        c.Deposit{value: deposit2}();

        // user1 collects collectAmount
        vm.prank(user1);
        c.Collect(collectAmount);

        // Invariant: sum of balances of all known users == totalDeposited - collectAmount
        uint256 sumBalances = c.balances(user1) + c.balances(user2);
        assertEq(sumBalances, totalDeposited - collectAmount);
    }
}

// Minimal LogFile implementation required by C
contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint256 Val;
        uint256 Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint256 _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

